import pytest
from transplant_twin.domain.units import convert


def test_convert_mg_to_mcg(value, source, target, expected):
    result = convert(value, source, target)
    assert result == pytest.approx(expected), f'Expected {expected}, got {result}'


def test_convert_mg_to_ng(value, source, target, expected):
    result = convert(value, source, target)
    assert result == pytest.approx(expected), f'Expected {expected}, got {result}'


def test_convert_mg_per_l_to_ng_per_ml(value, source, target, expected):
    result = convert(value, source, target)
    assert result == pytest.approx(expected), f'Expected {expected}, got {result}'


def test_convert_mg_to_mg(value, source, target, expected):
    result = convert(value, source, target)
    assert result == pytest.approx(expected), f'Expected {expected}, got {result}'


def test_convert_mg_to_mg_rejects(value, source, target):
    with pytest.raises(ValueError):
        convert(value, source, target)


def test_convert_unknown_unit_rejects(value, source, target):
    with pytest.raises(ValueError):
        convert(value, source, target)


def test_convert_nan_inf_rejects(value, source, target):
    with pytest.raises(ValueError):
        convert(value, source, target)
